async function* transform(src, sink) {
  for await (const chunk of src) {        // pull: the producer waits for us
    if (!sink.write(chunk)) {             // false => buffer is full
      await once(sink, 'drain');          // resume only when there is room
    }
  }
  sink.end();
}
